import io
import zipfile
from flask import Flask, request, send_file, jsonify

app = Flask(__name__)

@app.route('/convert', methods=['POST'])
def convert():
    if 'file' not in request.files:
        return jsonify({"error": "No file part"}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "No selected file"}), 400

    if not file.filename.endswith('.zip'):
        return jsonify({"error": "File must be a zip file"}), 400

    try:
        zip_stream = io.BytesIO(file.read())
        text_parts = []
        with zipfile.ZipFile(zip_stream, 'r') as zf:
            for name in zf.namelist():
                if name.endswith('.txt') or name.endswith('.text'):
                    content = zf.read(name).decode('utf-8', errors='replace')
                    text_parts.append(content)
                elif not any(name.endswith(ext) for ext in ['.png', '.jpg', '.jpeg', '.gif', '.bmp', '.ico', '.pdf', '.exe', '.bin', '.dat']):
                    # Try to read as text for unknown files
                    try:
                        content = zf.read(name).decode('utf-8', errors='replace')
                        text_parts.append(content)
                    except Exception:
                        pass
        result = "\n".join(text_parts)
        return send_file(
            io.BytesIO(result.encode('utf-8')),
            mimetype='text/plain',
            as_attachment=True,
            download_name='converted.txt'
        )
    except zipfile.BadZipFile:
        return jsonify({"error": "Invalid zip file"}), 400
    except Exception as e:
        return jsonify({"error": str(e)}), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

