import os
import zipfile
import io
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/convert', methods=['POST'])
def convert():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if not file.filename.endswith('.zip'):
        return jsonify({'error': 'File must be a zip file'}), 400

    try:
        zip_stream = io.BytesIO(file.read())
        with zipfile.ZipFile(zip_stream, 'r') as zf:
            # Check for nested zip bombs by limiting the number of files and total size
            file_list = zf.namelist()
            if len(file_list) > 500:
                return jsonify({'error': 'Too many files in archive'}), 400

            text_parts = []
            for name in file_list:
                try:
                    # Prevent path traversal and check for nested zips
                    if name.startswith('../') or '/..' in name:
                        continue
                    # Skip files that look like they might be nested archives
                    if name.endswith('.zip') or name.endswith('.ZIP'):
                        continue
                    content = zf.read(name)
                    # Limit individual file size to prevent bomb
                    if len(content) > 10 * 1024 * 1024:  # 10MB
                        continue
                    text = content.decode('utf-8', errors='replace')
                    text_parts.append(text)
                except Exception:
                    continue
            result = ''.join(text_parts)
        return jsonify({'text': result}), 200
    except zipfile.BadZipFile:
        return jsonify({'error': 'Invalid zip file'}), 400
    except Exception as e:
        return jsonify({'error': str(e)}), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
